import * as React from "react"
import { motion, useInView, animate, useMotionValue } from "framer-motion"
import { addPropertyControls, ControlType } from "framer"

type Direction = "up" | "down" | "random"
type EasingPreset = "smooth" | "linear" | "easeOut" | "springy"

interface Props {
    startValue?: number
    endValue?: number
    duration?: number
    fontSize?: number
    color?: string
    decimals?: number
    direction?: Direction
    prefix?: string
    suffix?: string
    easingPreset?: EasingPreset
    stagger?: number
    font?: any
}

const defaultFont = {
    fontSize: "92px",
    variant: "Bold",
    letterSpacing: "0em",
    lineHeight: "1em",
}

const defaultProps: Props = {
    startValue: 0,
    endValue: 139373,
    duration: 2.5,
    fontSize: 92,
    color: "#00154b",
    decimals: 0,
    direction: "up",
    prefix: "",
    suffix: "",
    easingPreset: "smooth",
    stagger: 0.08,
    font: defaultFont,
}

const easingMap: Record<EasingPreset, any> = {
    smooth: [0.16, 1, 0.3, 1],
    linear: "linear",
    easeOut: [0.19, 1, 0.22, 1],
    springy: [0.25, 1.4, 0.5, 1],
}

// ==============================================
// DIGIT COMPONENT
// ==============================================
const Digit = ({
    motionValue,
    marginLeft,
    marginRight,
}: {
    motionValue: any
    marginLeft: number
    marginRight: number
}) => {
    const numbers = [...Array(10)].map((_, i) => i)

    return (
        <div
            style={{
                height: "1em",
                overflow: "hidden",
                marginLeft,
                marginRight,
            }}
        >
            <motion.div
                style={{
                    y: motionValue,
                    display: "flex",
                    flexDirection: "column",
                    gap: 0,
                }}
            >
                {numbers.map((n) => (
                    <span
                        key={n}
                        style={{
                            height: "1em",
                            lineHeight: "1em",
                            display: "block",
                        }}
                    >
                        {n}
                    </span>
                ))}
            </motion.div>
        </div>
    )
}

// ==============================================
// MAIN COMPONENT
// ==============================================
export function RollingDigitCounter(props: Props) {
    const {
        startValue,
        endValue,
        duration,
        fontSize,
        color,
        decimals,
        direction,
        prefix,
        suffix,
        easingPreset,
        stagger,
        font,
    } = { ...defaultProps, ...props }

    const ref = React.useRef<HTMLDivElement>(null)
    const isInView = useInView(ref, {
        once: true,
        margin: "0px 0px -100px 0px",
    })

    const easing = easingMap[easingPreset || "smooth"]
    const staggerAmount = stagger ?? 0.08

    // ----------------------------------------------
    // TYPOGRAPHY + LETTER-SPACING → PER-DIGIT SPACING
    // ----------------------------------------------
    const { fontStyle, digitHeight, baseSpacing } = React.useMemo(() => {
        const f = (font as any) || {}
        const { letterSpacing, ...rest } = f

        const size = rest.fontSize || `${fontSize}px`
        let height = typeof size === "string" ? parseFloat(size) : size

        let spacingPx = 0
        if (typeof letterSpacing === "string") {
            if (letterSpacing.endsWith("em"))
                spacingPx = parseFloat(letterSpacing) * height
            else spacingPx = parseFloat(letterSpacing)
        } else if (typeof letterSpacing === "number") {
            spacingPx = letterSpacing
        }

        return {
            fontStyle: {
                ...rest,
                fontSize: size,
                fontVariantNumeric: "tabular-nums",
            },
            digitHeight: height,
            baseSpacing: spacingPx,
        }
    }, [font, fontSize])

    // ------------------------------------------------------
    //  ORDER & DECIMALS
    // ------------------------------------------------------
    let from = startValue ?? 0
    let to = endValue ?? 0

    const actualDirection =
        direction === "random"
            ? Math.random() > 0.5
                ? "up"
                : "down"
            : direction

    if (actualDirection === "up" && from > to) [from, to] = [to, from]
    if (actualDirection === "down" && from < to) [from, to] = [to, from]

    const formatNumber = (v: number) => {
        const s = String(v)
        if (!decimals || decimals <= 0) return s
        const [i, d] = s.split(".")
        if (!d) return i
        return `${i}.${d.slice(0, decimals)}`
    }

    const fromStr = formatNumber(from)
    const toStr = formatNumber(to)
    const maxLen = Math.max(fromStr.length, toStr.length)

    const fromChars = fromStr.padStart(maxLen, " ").split("")
    const toChars = toStr.padStart(maxLen, " ").split("")

    // motion values for each digit
    const digitMotionValues = toChars
        .filter(
            (char, i) => !isNaN(Number(char)) && !isNaN(Number(fromChars[i]))
        )
        .map(() => useMotionValue(0))

    // ------------------------------------------------------
    //  ANIMATE ON VIEW
    // ------------------------------------------------------
    const motionIndexRef = React.useRef(0)

    React.useEffect(() => {
        if (!isInView) return
        motionIndexRef.current = 0

        toChars.forEach((char, i) => {
            const fromChar = fromChars[i]
            if (isNaN(Number(char)) || isNaN(Number(fromChar))) return

            const mv = digitMotionValues[motionIndexRef.current]
            motionIndexRef.current++

            const fromDigit = Number(fromChar)
            const toDigit = Number(char)

            mv.set(-digitHeight * fromDigit)

            animate(mv, -digitHeight * toDigit, {
                duration,
                ease: easing,
                delay: i * staggerAmount,
            })
        })
    }, [isInView, digitHeight, duration, easing, staggerAmount, fromStr, toStr])

    let currentIndex = 0

    const justify =
        fontStyle.textAlign === "center"
            ? "center"
            : fontStyle.textAlign === "right"
              ? "flex-end"
              : "flex-start"

    // ------------------------------------------------------
    //  ⭐ KERNING FIX FOR DIGIT "1"
    // ------------------------------------------------------
    const ONE_KERN_FACTOR = 0.25 // 👈 YOU ASKED FOR THIS — HERE IT IS
    // tweak this between 0.18 – 0.32 if needed

    return (
        <div
            ref={ref}
            style={{
                display: "flex",
                alignItems: "center",
                justifyContent: justify,
                color,
                ...fontStyle,
            }}
        >
            {prefix && (
                <span
                    style={{
                        height: "1em",
                        lineHeight: "1em",
                        marginRight: baseSpacing,
                    }}
                >
                    {prefix}
                </span>
            )}

            {toChars.map((char, i) => {
                const isDigit = !isNaN(Number(char))
                const prev = toChars[i - 1]
                const next = toChars[i + 1]

                let marginLeft = 0
                let marginRight = i === toChars.length - 1 ? 0 : baseSpacing

                // -- KERNING: Fix spacing when "1" has neighbours --
                if (isDigit && char === "1") {
                    const adjust = digitHeight * ONE_KERN_FACTOR

                    if (prev && !isNaN(Number(prev))) marginLeft -= adjust * 0.6
                    if (next && !isNaN(Number(next))) marginRight -= adjust
                }

                if (isDigit) {
                    const mv = digitMotionValues[currentIndex]
                    currentIndex++
                    return (
                        <Digit
                            key={i}
                            motionValue={mv}
                            marginLeft={marginLeft}
                            marginRight={marginRight}
                        />
                    )
                }

                return (
                    <span
                        key={i}
                        style={{
                            height: "1em",
                            lineHeight: "1em",
                            marginLeft,
                            marginRight,
                            alignSelf: "flex-end",
                        }}
                    >
                        {char}
                    </span>
                )
            })}

            {suffix && (
                <span
                    style={{
                        height: "1em",
                        lineHeight: "1em",
                        marginLeft: baseSpacing,
                    }}
                >
                    {suffix}
                </span>
            )}
        </div>
    )
}

// ==============================================
// CONTROLS
// ==============================================
RollingDigitCounter.defaultProps = {
    ...defaultProps,
    width: 400,
    height: 120,
}

addPropertyControls(RollingDigitCounter, {
    font: {
        type: ControlType.Font,
        title: "Font",
        controls: "extended",
        defaultFontType: "sans-serif",
        defaultValue: defaultFont,
    },
    color: {
        type: ControlType.Color,
        title: "Color",
        defaultValue: defaultProps.color,
    },
    startValue: {
        type: ControlType.Number,
        title: "Start",
        defaultValue: defaultProps.startValue,
    },
    endValue: {
        type: ControlType.Number,
        title: "End",
        defaultValue: defaultProps.endValue,
    },
    decimals: {
        type: ControlType.Number,
        title: "Decimals",
        min: 0,
        max: 10,
        step: 1,
        defaultValue: defaultProps.decimals,
    },
    direction: {
        type: ControlType.SegmentedEnum,
        title: "Direction",
        options: ["up", "down", "random"],
        defaultValue: defaultProps.direction,
    },
    prefix: {
        type: ControlType.String,
        title: "Prefix",
        defaultValue: defaultProps.prefix,
    },
    suffix: {
        type: ControlType.String,
        title: "Suffix",
        defaultValue: defaultProps.suffix,
    },
    duration: {
        type: ControlType.Number,
        title: "Duration",
        min: 0.1,
        max: 10,
        step: 0.1,
        defaultValue: defaultProps.duration,
    },
    fontSize: {
        type: ControlType.Number,
        title: "Base size",
        min: 8,
        max: 200,
        defaultValue: defaultProps.fontSize,
    },
    easingPreset: {
        type: ControlType.Enum,
        title: "Easing",
        options: ["smooth", "linear", "easeOut", "springy"],
        defaultValue: defaultProps.easingPreset,
    },
    stagger: {
        type: ControlType.Number,
        title: "Stagger",
        min: 0,
        max: 0.5,
        step: 0.01,
        defaultValue: defaultProps.stagger,
    },
})
